def f(x):
    return x**2 * (x - 1)

# Check monotonicity for positive integers
for x in range(1, 10):
    print(f"f({x}) = {f(x)}")

# Check for equal values among distinct inputs (x1 != x2)
for x1 in range(1, 10):
    for x2 in range(x1 + 1, 10):
        if f(x1) == f(x2):
            print(f"Found equal values: f({x1}) = f({x2}) = {f(x1)}")
